INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-14', 'Itachi Uchiha', 'anime', 'anilist', '14', 0.5402332647260609, 'https://s4.anilist.co/file/anilistcdn/character/large/b14-9Kb1E5oel1ke.png', '__Height:__ 175 cm Itachi Uchiha is a missing-nin from Konohagakure, and a prominent member of Akatsuki, partnered with [Kisame Hoshigaki](https://anilist.co/character/2672). He is [Sasuke Uchiha](https://anilist.co/character/13)''s older brother. Ever since his first appearance, Itachi had always been mysterious, and had acted as though he was hiding his true self. While flashbacks to his past showed that he was a compassionate brother and person, his later acts and claims made it seem that t...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-137080', 'Makima', 'anime', 'anilist', '137080', 0.5392531608350485, 'https://s4.anilist.co/file/anilistcdn/character/large/b137080-UHcynYNjb5ZU.png', '__Height:__ 168 cm (5''6") __Affiliation:__ Public Safety Devil Hunters Makima is a Public Safety Devil Hunter, who took [Denji](https://anilist.co/character/130102/Denji) as her human pet. She is one of the leading figures of Public Safety in Japan and has a considerable reputation among experienced Devil Hunters.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127222', 'Mai Sakurajima', 'anime', 'anilist', '127222', 0.5295501323140253, 'https://s4.anilist.co/file/anilistcdn/character/large/b127222-Jh5hhP7vZ7s1.png', '__Height:__ 162 cm (5''4") A 3rd-year student at Minegahara High School. She is serious and polite, but has a strong will. Well known, famous actress, who is currently on hiatus. Because her life had always revolved around her work in entertainment, she remains isolated at school. (Source: Aniplex USA)');
