INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-133700', 'Nobara Kugisaki', 'anime', 'anilist', '133700', 0.34391845535626775, 'https://s4.anilist.co/file/anilistcdn/character/large/b133700-f6sOO3TcgLV6.png', '__Height:__ 160 cm (5''3") __Occupation:__ Jujutsu Sorcerer, Student __Affiliation:__ Tokyo Jujutsu High __Grade:__ Grade 3 Sorcerer She is a first-year student and grade 3 jujutsu sorcerer at Tokyo Jujutsu High studying under [Satoru Gojo](https://anilist.co/character/127691) alongside [Yuji](https://anilist.co/character/127212) and [Megumi](https://anilist.co/character/126635). Nobara is a confident and brash young woman with an unshakable character. More than anything, Nobara is determined ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-23602', 'Shinobu Oshino', 'anime', 'anilist', '23602', 0.34186023718514164, 'https://s4.anilist.co/file/anilistcdn/character/large/b23602-Z4MDNYcoAWZu.png', 'A girl who lives with [Oshino Meme](https://anilist.co/character/22552/Meme-Oshino) in an abandoned building. She loves donuts from the Mister Donut chain. At the beginning of Hitagi Crab, she was renamed "Shinobu" by Meme, who suggested that the name Shinobu (忍), comprised of a heart (心) under a blade (刃), matched her original persona.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-64771', 'Tobio Kageyama', 'anime', 'anilist', '64771', 0.34102714887778107, 'https://s4.anilist.co/file/anilistcdn/character/large/b64771-BuCVs7B8bBdh.png', '__Team:__ Karasuno High, Kitagawa Daiichi Junior High (former) __Height:__ 180.6 cm __Year:__ 1st Year, class 3 __Number:__ 9 __Position:__ Setter A famous setter in his middle school who joins the Karusuno High Volleyball team. He was known as the "King of the Court" in his middle school because of his arrogant demeanor and the way he would order around his teammates. Although he still carries an overbearing attitude, he begins to change when he starts to play with [Hinata Shouyou](https://a...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-84677', 'Yato', 'anime', 'anilist', '84677', 0.3356855826717632, 'https://s4.anilist.co/file/anilistcdn/character/large/b84677-PFmohzIXD1ud.png', '__Race:__ God __Height:__ 174 cm (5’8”) __Occupation:__ God of War, Delivery God, God of Calamity (previously) Yato is one of the three main protagonists of Noragami. An obscure god who considers himself a God of Fortune / Happiness and War, he has been labeled a God of Calamity and Depression in the past. Yato''s dream is to become a famous god, whom everyone worships. Yato can be mischievous, crude, and unpredictable in his behavior. He often has a low tolerance for something he wants, usual...');
