INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-161700', 'Ashuna Grizarica', 'anime', 'anilist', '161700', 0.024796628442614918, 'https://s4.anilist.co/file/anilistcdn/character/large/b161700-q3m4O6IR4tLh.png', 'Traveling Princess Knight. Princess of the Grizarica Kingdom, who is strong and beautiful. People call her the "Princess Knight" and she carries a sword with the royal crest as she always is ready for a fight.');
