INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-1151', 'Ikkaku Madarame', 'anime', 'anilist', '1151', 0.019749093403900814, 'https://s4.anilist.co/file/anilistcdn/character/large/b1151-izBrO6oWMvDv.png', '__Height:__ 182cm (6''0") Ikkaku Madarame is the 3rd Seat of the 11th Division in the Gotei 13. His captain is Kenpachi Zaraki. In terms of his attitude, Ikkaku is a stereotypical 11th Division member — violent, fight-loving, and rude. This has been noted by Tetsuzaemon Iba, among others. He loves fighting so much that he is unwilling to travel anywhere without a sword, resorting to carrying a wooden one when posing as a student at Ichigo Kurosaki''s school. However, Ikkaku does have a sense of...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-66597', 'Marika Tachibana', 'anime', 'anilist', '66597', 0.019724590806625503, 'https://s4.anilist.co/file/anilistcdn/character/large/b66597-uvxnKDUNlSJZ.png', '**Height:** 152 cm Marika transfers to [Raku](https://anilist.co/character/48393/Raku-Ichijou)''s class and is introduced as his fiancée; she bears a key that she thinks will unlock Raku''s pendant, and is the most vocal about expressing her love to Raku. She is the daughter of the police chief, and has been in love with Raku for the past ten years. She does not get along with [Chitoge](https://anilist.co/character/48391/Chitoge-Kirisaki); she states she hates girls with long hair despite the f...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-280138', 'Nagomi Wahira', 'anime', 'anilist', '280138', 0.01970008820935019, 'https://s4.anilist.co/file/anilistcdn/character/large/b280138-lx72YdJwb69p.png', '**Height:** 154 cm A fresh-faced 17-year-old girl who moves to Akiba to become a maid cafe waitress after seeing a flier from the Oinky Doink Cafe. Despite her initial enthusiasm, Nagomi quickly becomes disillusioned when she gets dragged into the schemes of the Cafe and her Manager as she begins to learn the hard reality of being a maid.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-125599', 'Asumi Kominami', 'anime', 'anilist', '125599', 0.01970008820935019, 'https://s4.anilist.co/file/anilistcdn/character/large/b125599-lRbcA9Ijf7yf.png', 'Part-time worker at a maid café called High Stage and classmates with [Yuiga](https://anilist.co/character/121777) at a summer cram school.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-38150', 'Riela Marcellis', 'anime', 'anilist', '38150', 0.01970008820935019, 'https://s4.anilist.co/file/anilistcdn/character/large/38150.jpg', 'Riela, also known as &quot;Number 13&quot;, is a young woman who initially does not know that she is a descendant of the Valkyria. During her time in the regular army, Riela became infamous as the lone survivor of many wiped-out army squadrons and now she became the burden for every squadron she is assigned at');
