INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-87519', 'Maria Otonashi', 'anime', 'anilist', '87519', 0.01631872978535725, 'https://s4.anilist.co/file/anilistcdn/character/large/b87519-Ub0XynImRFw5.jpg', 'An antisocial beauty with a resolute personality. She transfers into Kazuki''s class on March 2nd—right before the end of the school year. Immediately upon her arrival, she announces her intent to “break” Kazuki.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-120755', 'Gray', 'anime', 'anilist', '120755', 0.016294227188081937, 'https://s4.anilist.co/file/anilistcdn/character/large/b120755-pPTdmFrsmG8z.jpg', 'Lord El-Melloi II''s assistant at the Mage''s Association''s Clock Tower.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-21093', 'Borsalino', 'anime', 'anilist', '21093', 0.016294227188081937, 'https://s4.anilist.co/file/anilistcdn/character/large/b21093-Pc4kOjUn3ZkZ.png', '__Affiliations:__ Marines __Occupations:__ Admiral; Vice Admiral (former) __Height:__ 302 cm (9''11") __Devil Fruit:__ Pika Pika no Mi (Glint-Glint Fruit) __Type:__ Logia Borsalino, more commonly known by his alias Kizaru, is an admiral in the Marines. He was first mentioned by Robin during the initial encounter with Aokiji. Kizaru can be considered the secondary antagonist of the Sabaody Archipelago Arc and one of the major antagonists of the Marineford Arc.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-2111', 'Videl', 'anime', 'anilist', '2111', 0.016294227188081937, 'https://s4.anilist.co/file/anilistcdn/character/large/b2111-9XqkV0tpjRPB.png', '__Race:__ Earthling __Height:__ 4''11" __Birth Year:__ 757 Age __Hobby:__ Serving as the Ally of Justice __Favorite Food:__ Okonomiyaki, Caesar Salad __Favorite Vehicle:__ Air Bike Videl is the daughter of Mr. Satan. Mr. Satan is very protective of her, especially in respect to boys. She grew up learning martial arts hoping to be as great as her dad, when in fact, unknown to herself she was already better than him. She is a tough, tomboyish character, raised with fame all around her. In her sp...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-215691', 'Jeanne d''Arc Alter', 'anime', 'anilist', '215691', 0.016269724590806625, 'https://s4.anilist.co/file/anilistcdn/character/large/b215691-3QKTkH6zoKFe.png', 'Also known as Jeanne Alter, she is the Alter version of Jeanne d''Arc. Although designated an Alter, it does not mean that she is a different aspect of Jeanne d''Arc. A Jeanne of vengeance that Gilles de Rais, the French Army''s marshal who grieved for Jeanne d''Arc''s death, fabricated by means of the Holy Grail shortly after the execution of Jeanne in 1431. As a Heroic Spirit that is an exact opposite of the proper Jeanne, she is manifesting in the Avenger Class. __In Fate/Samurai Remnant:__');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-174874', 'Theoto Rikka', 'anime', 'anilist', '174874', 0.016269724590806625, 'https://s4.anilist.co/file/anilistcdn/character/large/b174874-19TPZgyNwDtj.jpg', '__Height:__ 165 cm Theoto Rikka is a platoon leader of the Eighty-Sixth Strike Package''s Spearhead Squadron and the artist of the squadron member''s Personal Marks. His Personal Name is Laughing Fox. Having survived four years on the Eastern Front and the Special Reconnaissance Mission, he is considered one of the most elite Processors alive.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-153703', 'Mini Yaemori', 'anime', 'anilist', '153703', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/b153703-KOLZ2Oz2sFDo.png', 'A streamer otaku who moved to the flat next to Kazuya and happens to go to the same college as him. Calls Kazuya "Master."');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-141457', 'Momo Chiyoda', 'anime', 'anilist', '141457', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/b141457-zbvICmxe7kgM.png', '**Momo Chiyoda** is the magical girl who is protecting the town of Seiiki Sakuraga-oka. As a magical girl, she is a maniac of muscle training, and her physical power overwhelmingly surpasses that of her rival [Yuuko](https://anilist.co/character/141461), the succubus in town. Her magical girl career is mysterious, including rumors that she had once saved the world.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-136544', 'Parona', 'anime', 'anilist', '136544', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/b136544-LGUvcdc4cyPY.jpg', '**Relatives:** Unnamed mother, father, and [sister](https://anilist.co/character/201557/Paronas-sister). Parona is a girl from Ninannah and a close friend of [March](https://anilist.co/character/136541/March). She looks after March like an older sister.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-80257', 'Yumiko Sakaki', 'anime', 'anilist', '80257', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/b80257-pelmvGBeCiNm.png', '__Height__: 163 cm A second-year at Mihama Academy, and the daughter of the East Beach Railway Express Group tycoon. She was the first student to enroll at Mihama Academy. She has waist-length black hair. Because of her bluntness and hard-to-please personality, she has difficulty talking to others. Always trying to be alone, she hardly spends time with the others. She always carries a box cutter with her and use it to threaten others when she’s angry. She is a bookworm, and mystery novels are...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-55839', 'Tsumiki Miniwa', 'anime', 'anilist', '55839', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/b55839-Yh2Uw1liMo0X.jpg', 'The shortest heroine and the tsundere in her circle of friends has a crush on Io. Every time when Io gives Tsumiki a pat on the head or sees something she likes, her hair changes shape into cat ears. Tsumiki is also left-handed.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-9700', 'Yusei Fudou', 'anime', 'anilist', '9700', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/b9700-5cbgNJYOtiOc.jpg', 'Yusei is a new and main character in this series. He is considered a rare duelist riding [Red D-Wheel]. Yusei is familiar with machine and computer, so he assembles D-Wheel by himself. His personality is very different from Judai in GX series but similar to Mutou Yugi. He looks cool and smart with hot heart especially in a duel and always thinks about his friends. After fighting Jack Atlas, [Dragon&#039;s Birthmark] appears on his arm and makes him become a Signer. The story mainly focuses on...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-1012', 'Majin Boo', 'anime', 'anilist', '1012', 0.016220719396256, 'https://s4.anilist.co/file/anilistcdn/character/large/1012.jpg', 'Boo is introduced in the series as an innocent looking, pudgy, pink genie-like creature. Later in the series, it is revealed that Boo''s original form is a more sleek child form ("The Boo of Pure Evil"), however his nature and form had been altered after he''d assimilated the gentle, pudgy god (Dai Kaioshin) into his body. Boo''s creator, a wizard named Bibbidi, had used Boo to wage war on the Kaioshin. Boo managed to assimilate two of the four Kaioshin, the second being the one who altered his ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-129813', 'Melty Q Melromarc', 'anime', 'anilist', '129813', 0.016196216798980693, 'https://s4.anilist.co/file/anilistcdn/character/large/b129813-quaY4dr807yx.png', 'The second princess of Melromarc. Melty is in many ways the exact opposite of her sister, Malty. This includes their personality, appearance, magic specialty (water vs fire), and color schemes (blue and white against red and brown).');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-88489', 'Kisumi  Shigino', 'anime', 'anilist', '88489', 0.016196216798980693, 'https://s4.anilist.co/file/anilistcdn/character/large/b88489-MBmQa3emPr07.jpg', 'Kisumi Shigino was the first-year junior high student who debuted in the second volume of the light novel High☆Speed! written by Kouji Ouji. Kisumi was the part of the basketball club back at Iwatobi Junior High School. He is said to be a refreshing boy and was very popular among females. (Source: Wikipedia)');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-215409', 'Aurora', 'anime', 'anilist', '215409', 0.016171714201705382, 'https://s4.anilist.co/file/anilistcdn/character/large/b215409-Y1Ti42451ivg.png', '__Race:__ Human A woman known as the Calamity Witch who once brought chaos and destruction to the world. In the Goddess'' Trial in the Sacred Land, she is summoned in reaction to Cid''s presence and does battle with him in the form of Shadow. Her body is sealed in the sanctuary, and after helping Cid to escape she disappears together with its destruction.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-139509', 'Kourai Hoshiumi', 'anime', 'anilist', '139509', 0.01614721160443007, 'https://s4.anilist.co/file/anilistcdn/character/large/b139509-A7frl9ySB6cc.png', '__Height:__ 169.2 cm (5''6.6") __Teams:__ Yurisei Middle School (Former); Kamomedai High __Number:__ 5 __Position:__ Outside Hitter, Ace Hoshiumi Originally planned on playing basketball, but he decided to join the volleyball team in second grade. His reason was listed as wanting to be free from his older brother, Akitomo, who constantly sneered at Hoshiumi over their height difference. Despite his reasoning at first, Hoshiumi soon came to love the sport as he watched official matches on TV.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-131613', 'Doppo Kannonzaka', 'anime', 'anilist', '131613', 0.01614721160443007, 'https://s4.anilist.co/file/anilistcdn/character/large/b131613-L7CcTclCFrpG.png', 'A normal office worker and one of the three members of Matenrou alongside Jinguji Jakurai and Izanami Hifumi. An employee for a medical device manufacturer and a member of Matenrou. Peculiar in that he''s not peculiar at all. Always exhausted by his work as a salaryman. He has a habit of muttering to himself. A major cynic and tends to look at everything negatively. His pessimistic personality leaves him with very few friends and his only childhood friend is Hifumi, from his elementary days. H...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-137972', 'Olruggio', 'anime', 'anilist', '137972', 0.01612270900715476, 'https://s4.anilist.co/file/anilistcdn/character/large/b137972-4sSEu1132KZM.png', 'He is a witch and serves as the Watchful Eye for Qifrey''s atelier. He has a gruff way of speaking but his magic is often described as "warm". He has created a lot of magical items, such as the Glowstone Path, the Snugstone and the Searneedle Wand. His specialty is fire-based magic. He is very caring to the apprentices and gives them things that might be helpful, as well as rushing to Qifrey''s aid, but every time someone points out he''s acting very nicely, he tries to brush it off as something...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-55137', 'Mayaka Ibara', 'anime', 'anilist', '55137', 0.01612270900715476, 'https://s4.anilist.co/file/anilistcdn/character/large/b55137-PO5CLLnbTwyg.png', '__Height:__ 148 cm (4''10") An inseparable friend who''s been in the same class with Houtarou since their first grade in elementary school. She is interested in Satoshi, which leads her to join the classic literature club. She is also a member of the Library and Manga Society. She has a blunt and frank personality and usually makes nicknames for some of her friends (i.e: Fuku-chan, Chi-chan).');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-752', 'Juri Arisugawa', 'anime', 'anilist', '752', 0.01612270900715476, 'https://s4.anilist.co/file/anilistcdn/character/large/b752-yiBtyANT48mG.png', '__Rose Color:__ Orange __Rose Bride:__ Ruka Tsuchiya __Sword:__ Rapier __(Anime) Drive to Duel:__ To disprove the power of miracles The captain of the academy''s fencing team, Juri is one of Ohtori''s most highly respected students, and even the teachers appear to be in awe of her. (Source: Wikipedia)');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-173812', 'Hahari Hanazono', 'anime', 'anilist', '173812', 0.016098206409879447, 'https://s4.anilist.co/file/anilistcdn/character/large/b173812-esAPFUOtQnKc.jpg', '__Type:__ MILF __Occupation:__ High School Chairwoman __Debut:__ Chapter 17 **Girlfriend No. 006** [Hakari](https://anilist.co/character/173759/Hakari-Hanazono)''s mother. Hahari appears as a very mature and sophisticated woman, until she sees something cute. She has an uncontrollable love for cute things, including children, as well as Rentarou and his family. When she sees something she finds cute, she may start drooling. Like her daughter, she is also a pervert towards Rentarou as she is sh...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127417', 'Kesshouban', 'anime', 'anilist', '127417', 0.016098206409879447, 'https://s4.anilist.co/file/anilistcdn/character/large/127417-mK2MxesD0nrb.jpg', 'Platelet is a type of cell working under the Platelet Division. She and her coworkers are responsible for reconstructing injuries and forming blood clots in the human body. Due to the Platelet''s actual cell size, they are depicted as children. Platelet is a small, adorable cell with waist-length caramel blonde hair and brown eyes. She wears the Platelet uniform and is always seen working with her fellow workers. Platelets play an important role in healing the body. They are powerless against ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-124383', 'Goro', 'anime', 'anilist', '124383', 0.016098206409879447, 'https://s4.anilist.co/file/anilistcdn/character/large/n124383-I6ZsEBQoETj3.jpg', 'Goro pilots the Franxx Delphinium with [Ichigo](https://anilist.co/character/124382).');
