INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127130', 'Ninny Spangcole', 'anime', 'anilist', '127130', 0.013280407723218661, 'https://s4.anilist.co/file/anilistcdn/character/large/b127130-WxTvKNlAfzxn.png', '__Race:__ Human __Affiliation:__ Wing Bind __Profession:__ Witch, Singer __Position:__ 2nd Order Conservation, Ranger "Pipers" __Partner:__ [Noel Niihashi](https://anilist.co/character/127129) __Base of Operations:__ Reverse London A Witch working for Wing Bind in Reverse London. She is the partner of Noel Niihashi.');
