INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-349528', 'Mo Sha', 'anime', 'anilist', '349528', 0.012496324610408704, 'https://s4.anilist.co/file/anilistcdn/character/large/b349528-grA5fC1dS0g1.png', '__Height:__ 180 cm A cool-headed hero who completes his mission without uttering a single word. He is loved by his many fans for the silence with which he completes his work and for the chiseled, handsome face behind the mask. (Source: Official Site)');
