INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-88934', 'Sakuya Tachibana', 'anime', 'anilist', '88934', 0.012471822013133392, 'https://s4.anilist.co/file/anilistcdn/character/large/88934-HPuAH9Ilg309.jpg', 'The sub-leader of first unit. She is a top-rank shooter, and her god arc is a sniper (old-type; long range). (Source: Wikipedia)');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-39758', 'Ryuuichi Kashima', 'anime', 'anilist', '39758', 0.012471822013133392, 'https://s4.anilist.co/file/anilistcdn/character/large/b39758-Y5UkhT4pUM1a.jpg', 'Older brother, babysitter, and has a very close relationship with his toddler brother Kotarou. Both his parents died in a plane crash, now Kotarou and Ryuuichi live alone.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-170178', 'Nagi Aoe', 'anime', 'anilist', '170178', 0.01244731941585808, 'https://s4.anilist.co/file/anilistcdn/character/large/b170178-kIFSaV4nQH2X.png', '__Height:__ 163 cm Nagi Aoe is an idol that recently moved into Kurose''s town, where she worked as a convenience store clerk. She has recently stepped down from her work as an idol.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-145062', 'Hyouga', 'anime', 'anilist', '145062', 0.01244731941585808, 'https://s4.anilist.co/file/anilistcdn/character/large/b145062-eCEE4J0RRGvt.jpg', '__Height:__ 189cm (6''2") Hyoga is a survivor who was revived by Tsukasa Shishio. Initially, he was an elite member of the Tsukasa Empire since he was depetrified by Tsukasa. Hyoga has an easy going attitude towards everything. Even in situation that do not work in his favour, he still remains calm. While he claims to share the same values as Tsukasa when it comes to only reviving the young and creating a community where no one takes from others, Hyoga himself is an elitist who believes in soc...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-89620', 'Tome Kurata', 'anime', 'anilist', '89620', 0.01244731941585808, 'https://s4.anilist.co/file/anilistcdn/character/large/b89620-C1z1mMLIlO17.png', '__School:__ Salt Middle School __School club: __Telepathy Club (President) Tome seems to be a slacker but is passionate about the possibility of using telepathy to contact extraterrestrials. However, when the Telepathy Club''s research into the matter bears no results, she quickly gives up. When she learns that Mob is an Esper, her passion is revitalized.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-81711', 'Lotte Jansson', 'anime', 'anilist', '81711', 0.01244731941585808, 'https://s4.anilist.co/file/anilistcdn/character/large/b81711-fd0bFfcJPeOz.png', '**Height:** 156 cm Lotte is shy, calm and timid, rarely ever getting angry. She is a kind-hearted girl who earnestly looks after Akko. Lotte is often concerned about Akko, given that her determination to become a witch like Shiny Chariot sometimes makes her go too far, and that she would forget the well-being of friends and people who wish to help her.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-2215', 'Akiha Tohno', 'anime', 'anilist', '2215', 0.01244731941585808, 'https://s4.anilist.co/file/anilistcdn/character/large/b2215-bRS7he0VrHrJ.png', '__Height:__ 160 cm Shiki''s younger sister and the current head of the Tohno family. She is very prim and proper and carries a grace and nobility about her.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-130862', 'Viktor Licht', 'anime', 'anilist', '130862', 0.012422816818582769, 'https://s4.anilist.co/file/anilistcdn/character/large/b130862-jScLEFMkfo27.png', '__Height:__ 187cm (6''1") __Affiliation:__ Special Fire Force Company 8 __Rank:__ Science Team (First Class Fire Soldier Head of Research(Haijima) Viktor Licht is company 8''s Science Officer. Viktor attended the Imperial University of Tokyo, where he wrote a thesis about Spontaneous Human Combustion. After graduating at the top of his class in record time, he joined Haijima Industries. Having locked himself away while doing research, he was eventually appointed head of incendiary research and ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-130477', 'Ariel', 'anime', 'anilist', '130477', 0.012422816818582769, 'https://s4.anilist.co/file/anilistcdn/character/large/b130477-Szp3TMGbCCab.png', 'The current Demon Lord. (Source: Kumo Desu ga, Nani ka? Wiki)');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-130267', 'Wanyin Jiang', 'anime', 'anilist', '130267', 0.012422816818582769, 'https://s4.anilist.co/file/anilistcdn/character/large/b130267-lxfJm8K1W2ml.png', 'Jiang Wanyin is the current leader of the Yunmeng Jiang Sect and the uncle of Jin Ling. He is more commonly known to other cultivators by his courtesy name, Jiang Wanyin, or his title, Sandu Shengshou.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-125397', 'Yui Yamada', 'anime', 'anilist', '125397', 0.012422816818582769, 'https://s4.anilist.co/file/anilistcdn/character/large/b125397-TtFXE0cUSkNl.jpg', 'A quiet girl who is in charge of greenification. She''s poor at sports and singing.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-6089', 'Kalluto Zoldyck', 'anime', 'anilist', '6089', 0.012422816818582769, 'https://s4.anilist.co/file/anilistcdn/character/large/n6089-ro8HdSKvlycB.jpg', 'Kalluto Zoldyck is the younger brother of Killua. He was initially introduced accompanying his mother during Gon''s retrieval of Killua from his home on Kukuroo Mountain. Kalluto appears again during the Yorknew City arc, assisting his older brother Illumi with the assassination of the ten mafia dons that placed bounties on the Phantom Troupe''s heads. After the Phantom Troupe''s entrance into Greed Island, Kalluto joins as Hisoka''s replacement. During the Phantom Troupe''s assault on Zazan''s pal...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-214583', 'Kenichirou Ryuuzaki', 'anime', 'anilist', '214583', 0.012398314221307459, 'https://s4.anilist.co/file/anilistcdn/character/large/b214583-akJm3W589tEd.png', 'An old friend of Akira Tendou from college and the rugby team. He hasn''t seen him in a year before the apocalypse. After he graduated from college he became a salesmen at a major real estate company because of his great communication skills. In reality he seems almost perfect but he too was miserable at his job and wanted to become a comedian.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-162035', 'Hana Ichijou', 'anime', 'anilist', '162035', 0.012398314221307459, 'https://s4.anilist.co/file/anilistcdn/character/large/b162035-goi3gRhYZErH.jpg', '__Height:__ 157 cm Hana Ichijou is the younger step-sister of [Tatsuya Fukuda](https://anilist.co/character/133817), the coach of Tokyo City Esperion FC Youth. She has been a football fan since she was very young. She was especially a fan of Fukuda, even before their parents married. Hana has a deep knowledge of nutrition as she aspires to become a sports surgeon. She uses that knowledge to make meal plans for the players, notably [Ashito](https://anilist.co/character/133818/Ashito--Aoi) and ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-153146', 'Hitomi Hino', 'anime', 'anilist', '153146', 0.012398314221307459, 'https://s4.anilist.co/file/anilistcdn/character/large/b153146-eqaew6n1EdmR.jpg', '__Species:__ Human The only other human in the academy, and incidentally, the only female human.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-136705', 'Michizou Tachihara', 'anime', 'anilist', '136705', 0.012398314221307459, 'https://s4.anilist.co/file/anilistcdn/character/large/b136705-qd9sowaD7SKW.png', '__Height:__ 176 cm __Ability:__ Midwinter Memento A commander of the Black Lizards, the Port Mafia''s squad of hitmen. Though he puts up a tough and violent front, he cares deeply for his friends. Very skilled gunner, especially when dual wielding.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-9482', 'Otsu', 'anime', 'anilist', '9482', 0.012398314221307459, 'https://s4.anilist.co/file/anilistcdn/character/large/9482.jpg', '__Affiliation:__ Miyamoto Village Childhood friend of Takezo and Matahachi. Otsu was raised by Matahachi''s family and arranged to marry Matahachi.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-2551', 'Goten Son', 'anime', 'anilist', '2551', 0.012398314221307459, 'https://s4.anilist.co/file/anilistcdn/character/large/2551.jpg', '__Race:__ Half Saiyan, Half-Human __Height:__ 123 cm (4'') __Birth Year:__ 767 __Hobbies:__ Playing War, Catching Bugs __Favorite Food:__ Pocky, Strawberry Daifuku __Favorite Vehicle:__ Bicycle Goten is a fictional character in the manga and anime series Dragon Ball Z, as well as appearing in Dragon Ball GT. He is the second son of Son Goku and Chi Chi. Goten is a Human-Saiyan hybrid, just like his older brother, Son Gohan. Son Goten''s natural physique almost perfectly replicates his father Go...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-220804', 'Tinasha', 'anime', 'anilist', '220804', 0.012373811624032147, 'https://s4.anilist.co/file/anilistcdn/character/large/b220804-NPcJNFbf3fQv.jpg', 'Lives at the top of a tower in the wilderness and is said to grant the wishes of those who climb to the top.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-213002', 'Hiroki Dan', 'anime', 'anilist', '213002', 0.012373811624032147, 'https://s4.anilist.co/file/anilistcdn/character/large/b213002-mEm5qX3FHV8d.jpg', 'Hiroki Dan is the main antagonist of "Trace: Kasouken Houi Kenkyuuin no Tsuisou" and the main protagonist of his spin-off "Brutal: Satsujin Keisatsukan no Kokuhaku". He is a highly ranked police investigator and a serial killer. Dan is part of the Investigation Division Unit 1 and the son of a former police superintendent General. He seeks out criminals who could not be convicted by the law, and kills them. According to his own testimony during a confession in a church, he admits to doing thi...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-191243', 'Yifan Zhuo', 'anime', 'anilist', '191243', 0.012373811624032147, 'https://s4.anilist.co/file/anilistcdn/character/large/b191243-PAlQsx9b2Q3q.png', 'Zhuo Yifan was the Magic Emperor or can also be called a Demonic Emperor. Because he had the (Nine Serenities) Ancient Emperor''s book the Book of Nine Secrets, he was targeted by all the attending experts and was even betrayed and killed by his student Zhao Cheng. Then his soul enters and comes back to life in a family servant boy named Zhuo Fan. Because the Magic of the Heart (Heart Demon) of the previous owner was holding him back, he must unite the child''s memories and cannot ignore the fa...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-168800', 'Rose Oriana', 'anime', 'anilist', '168800', 0.012373811624032147, 'https://s4.anilist.co/file/anilistcdn/character/large/b168800-eb3FqWq0IdyV.png', '__Race:__ Human Rosa Oriana is a noble Princess from the Oriana kingdom. She is known for being a genius in art in her kingdom. However, she came to Midgar Royal Spellsword Academy in order to learn swordsmanship. (Source: To Be a Power in the Shadows! Wiki)');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-131621', 'Souta Kazama', 'video-games', 'anilist', '131621', 0.012373811624032147, 'https://s4.anilist.co/file/anilistcdn/character/large/b131621-93Jca5HnFFUn.png', 'Kazama Souta is one of the secondary characters in My Senpai is Annoying. He is a senpai at Igarashi Futaba''s company. Kazama is a young adult with short black hair, who can be seen in a white button-up shirt with black working pants and occasionally, a blue necktie. Kazama is boring and gives a boring look, and seemingly doesn''t have many friends. He prefers to spend the New Year alone playing video games. He also has a hobby of making origami. His ears are sensitive.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-89154', 'Pandora''s Actor', 'anime', 'anilist', '89154', 0.012373811624032147, 'https://s4.anilist.co/file/anilistcdn/character/large/89154-jbsFsEsjL3aS.jpg', '__Height:__ 177cm __Race:__ Doppelgänger __Affiliation:__ Great Tomb of Nazarick __Occupation:__ Area Guardian of the Treasury __Creator:__ Ainz Ooal Gown (Momonga) __Hobby:__ Managing Magic Items The Area Guardian in charge of the Treasury and finances of Nazarick, who was created by Ains himself. He''s a Doppelgänger whose face is a simple egghead with three holes dressed in a Neo-Nazi-esque uniform. In Momonga''s original design, he''s the combination of everything that he thought was cool, w...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-306965', 'Guita Heavy Fantasia', 'anime', 'anilist', '306965', 0.012349309026756836, 'https://s4.anilist.co/file/anilistcdn/character/large/b306965-O9SMKXV4LB4f.jpg', '__Affiliation:__ Cleaners __Jinki:__ "Guita" __Height:__ 148 cm (4’10”) Guita Heavy Fantasia is a Giver who works for the Cleaners as a member of ''Team Child''. She is a loud, silly teenage girl with a deep love for animals and monsters.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-169404', 'Gin Gagamaru', 'anime', 'anilist', '169404', 0.012349309026756836, 'https://s4.anilist.co/file/anilistcdn/character/large/b169404-90OF8t2ukD9H.jpg', '__Height:__ 191 cm Gagamaru was a forward who aspired to be the best in the world, along with the others of Blue Lock. When first arriving at Blue Lock, he was a member of Team Z during the First Selection.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-76346', 'Whis', 'anime', 'anilist', '76346', 0.012349309026756836, 'https://s4.anilist.co/file/anilistcdn/character/large/b76346-BNh2DE5Rh2IW.jpg', 'Whis (ウイス, Uisu) is the Guide Angel Attendant of Universe 7''s God of Destruction, Beerus, as well as his martial arts teacher. Along with the other angels, he is a child of the Grand Minister. Like all attendants, he is bound to the service of his deity and usually does not leave Beerus unaccompanied.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-14343', 'Epsilon', 'anime', 'anilist', '14343', 0.012349309026756836, 'https://s4.anilist.co/file/anilistcdn/character/large/b14343-OPQO2909RH9a.jpg', 'Photon-powered advanced robot who dislikes fighting and cares for homeless children. Created for war along with the other advanced ones, but refused to go there because of his pacifistic beliefs. Arguably the strongest out of the war series, Epsilon uses the Sun itself as his power source, capable of launching various heat and light based attacks, as well as creating photon-shields and manipulating photons. Epsilon is also capable of willingly detaching his own hands and controlling them remo...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-12306', 'Yuusaku Kitamura', 'anime', 'anilist', '12306', 0.012349309026756836, 'https://s4.anilist.co/file/anilistcdn/character/large/b12306-Nb1orOh4UkpT.png', 'Yuusaku is a male student in Ryuuji''s class, and is his best friend. He is the vice-president of the student council, the class representative, and captain of the boy''s softball club at school. Yuusaku wears glasses, and has a diligent personality. He thinks he is poor at talking to girls, though Ryuuji observes otherwise. During his time as the vice-president of the student council, he eventually falls in love with the student council president, Sumire Kanou. A running gag is that he will ap...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-4959', 'Naomi Misora', 'anime', 'anilist', '4959', 0.012349309026756836, 'https://s4.anilist.co/file/anilistcdn/character/large/b4959-DKXw1VYrvael.png', 'Naomi is a former "first rate" FBI agent who is engaged to [Raye Penber](https://anilist.co/character/7044). She is very intelligent, however she often lets her feelings get in the way of her investigative abilities. Naomi is notable for having worked alongside [L Lawlet](https://anilist.co/character/71) in the past to solve the Los Angeles BB Serial Murder case, which was what initally helped launch Naomi''s reputation within the FBI. Misora later left the FBI and became the fianc&eacute;e of...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-135198', 'Mirellia Q Melromarc', 'anime', 'anilist', '135198', 0.012324806429481526, 'https://s4.anilist.co/file/anilistcdn/character/large/b135198-ImEXzNG3srwI.png', 'The queen of Melromarc. She holds the true power of the crown and is generally a just ruler. She is known for her diplomacy and negotiation skills.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127463', 'Urushi Yaotome', 'anime', 'anilist', '127463', 0.012324806429481526, 'https://s4.anilist.co/file/anilistcdn/character/large/b127463-RSR8LH6O4byW.png', '__Grade:__ 3rd Year of High School __Height:__ 149.7 cm She''s one of the two members of the shogi club and the Self-proclaimed president of it.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-3789', 'Sana Kurata', 'anime', 'anilist', '3789', 0.012324806429481526, 'https://s4.anilist.co/file/anilistcdn/character/large/3789.jpg', '(at the beginning of the series) Sana Kurata is an 11-year-old child actress in the 6th grade that is the main star of the hit TV show ''Child''s Toy''. Sana is a natural born leader who is very curious, stubborn, and loves to help others out with their problems. She''s always cheerful, talkative, and full of spunk. Her family is made up of mother Misako Kurata, who is a famous author, and a man named Rei that she took in and made her manager. At school, she becomes enemies with a boy named Akito...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-175658', 'Seri Kikyou', 'anime', 'anilist', '175658', 0.012300303832206214, 'https://s4.anilist.co/file/anilistcdn/character/large/b175658-orkKzYl8kMtW.png', 'Seri Kikyou is a vampire and a gyaru that seeks enjoyment in life and finds it increasingly challenging to have fun.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-171898', 'Charon', 'anime', 'anilist', '171898', 0.012300303832206214, 'https://s4.anilist.co/file/anilistcdn/character/large/b171898-sOFT5nvhIsET.jpg', '__Type:__ Second Generation Charon is a member of the White-Clad, that serves as the Second Pillar''s guardian. He appears to be a devoted member of the White-Clad with a strong loyalty to the Evangalist. He takes his role as a guardian very seriously with protecting pillars at even risking the cost of his life. Charon has taken care of Haumea since she was young although she doesn’t seem to appreciate his efforts. He is very durable and is a expert in hand to hand combat with being very confi...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-85153', 'Hajime Ichinose', 'anime', 'anilist', '85153', 0.012300303832206214, 'https://s4.anilist.co/file/anilistcdn/character/large/85153-1qeDfjAGSsgA.png', '**Height:** 155 cm The main character of the story, Hajime is an 11th grader attending a high school in Tachikawa City. A powerful and energetic girl with an artistic spirit, she is a little bit strange in a good way. She has a passion for stationery goods, and gets extremely excited when it comes to different models of pens and scissors. She is put under the responsibility of Sugune, but usually goes against him and acts on her own. However, she greatly affects the world and her team members...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-163186', 'Tecchou Suehiro', 'anime', 'anilist', '163186', 0.012275801234930902, 'https://s4.anilist.co/file/anilistcdn/character/large/b163186-tDRfnLb1YGkH.png', '__Ability:__ Plum Blossoms in Snow Tecchou Suehiro is a Hunting Dogs special unit member with the ability Plum Blossoms in Snow. Tecchou has a considerably more serious demeanor than his companions, yet he still qualifies as an oddball for his strange preferences in food. He takes his duty as a Hunting Dog earnestly and has a deep sense of justice. He despises the notion of torture and is a highly compassionate person. Tecchou''s ability, Plum Blossoms in Snow, lets him enhance the size, shape...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127210', 'Nobunaga Oda', 'anime', 'anilist', '127210', 0.012275801234930902, 'https://s4.anilist.co/file/anilistcdn/character/large/b127210-hTvfTuQMyP4c.png', '__Height:__ 152cm Demon Archer is the Archer-class Servant in the Strange Tales of the Imperial Holy Grail of Koha Ace. She is one of the Servants of the Protagonist of the Grand Order conflicts of Fate/Grand Order.Haughty and self-confident, she possesses a flexible way of thinking that loves new things and is not bound by conservatism and common sense.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-181', 'Tomo Takino', 'anime', 'anilist', '181', 0.012275801234930902, 'https://s4.anilist.co/file/anilistcdn/character/large/n181-hUWUsjNmC6Mk.png', 'Tomo Takino is extremely energetic and competitive, despite being nonathletic and a slacker at the same time. She tends to irritate everyone around her, especially Yomi, who has been her classmate since elementary school. Tomo''s character is extremely impulsive and never considers nor cares about the consequences of anything she says or does. However, on the occasions when Tomo has actually been inspired to concentrate on something, she has demonstrated that she is quite capable. She succeede...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-189870', 'Kasumi Yoshizawa', 'anime', 'anilist', '189870', 0.012251298637655592, 'https://s4.anilist.co/file/anilistcdn/character/large/b189870-sf7R3OXJkT53.png', '__Height:__ 162 cm __Initial Persona:__ Cendrillon __Ultimate Persona:__ Vanadis Kasumi Yoshizawa, is a playable character from Persona 5 Royal. She is a talented gymnast studying at Shujin Academy who gets involved with the Phantom Thieves of Hearts.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-135231', 'Chizuru Tachibana', 'anime', 'anilist', '135231', 0.012251298637655592, 'https://s4.anilist.co/file/anilistcdn/character/large/b135231-aeA1xsueoUcy.jpg', 'Chizuru Tachibana is the 24 year old school nurse at Kawanuma East who is known as "Absolute Zero Tachibana" for her cold and expressionless attitude towards the students.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-85841', 'Emi Igawa', 'anime', 'anilist', '85841', 0.012251298637655592, 'https://s4.anilist.co/file/anilistcdn/character/large/b85841-728eVWAvzifr.png', 'Emi is a pianist of the same year as Kousei, who decided to become a pianist after listening to Kousei play at the age of 5. Emi is very emotional and her piano performance often depends on her mood on that day.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-250555', 'Suma', 'anime', 'anilist', '250555', 0.01222679604038028, 'https://s4.anilist.co/file/anilistcdn/character/large/b250555-jmjxCYpywW03.jpg', 'Suma is a kunoichi and one of Tengen Uzui''s wives.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-211161', 'Bisco Akaboshi', 'anime', 'anilist', '211161', 0.01222679604038028, 'https://s4.anilist.co/file/anilistcdn/character/large/b211161-TI6jm5TNqYKk.png', '__Height:__ 180 cm __Occupation:__ Mushroom Keeper A mushroom protector with the nickname of "Man-Eating Mushroom" who is regarded as a terrorist and has a price on his head. He commands a giant crab named Actagawa that is also used as for transport.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126665', 'Claudine Saijou', 'anime', 'anilist', '126665', 0.01222679604038028, 'https://s4.anilist.co/file/anilistcdn/character/large/126665-wyEBDhnZubpC.png', 'She is a character in the Shōjo☆Kageki Revue Starlight franchise. She is a second-year student from the Actor Training Department at Seisho Music Academy''s 99th Graduating Class, as well as the second seat in the class. Born to a Japanese father and a French mother, this talented Stage Girl already has a long career as a child actress. Upon entering the school, she meets the brilliant Maya Tendo and immediately begins a staunch rivalry.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-122696', 'Itsuki Sumeragi', 'anime', 'anilist', '122696', 0.01222679604038028, 'https://s4.anilist.co/file/anilistcdn/character/large/b122696-Ap3xm4l14BPQ.jpg', 'She''s a first-year student belonging to the "flower" class at Hyakkaou Private Academy and a member of the Student Council. Her father is the president of a prominent toy company in Japan. Her hobby is collecting other people’s nails.');
