INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-4775', 'Asuma Sarutobi', 'anime', 'anilist', '4775', 0.011761246692149369, 'https://s4.anilist.co/file/anilistcdn/character/large/b4775-skviHvjIQHiE.png', '__Rank:__ Jounin Asuma is the leader of Team 10 (Nara Shikamaru, Yamanaka Ino, Akimichi Chouji), Kurenai''s lover and the son of the third Hokage. Asuma smokes often but despite that, his skills are respected. He primarily uses Chakra Blades and can quickly dispatch his foes when the situation warrants. He is also proficient in Wind and Fire elements.');
