INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-162723', 'Taiyou Asano', 'anime', 'anilist', '162723', 0.010046064882877586, 'https://s4.anilist.co/file/anilistcdn/character/large/b162723-2veq2yEY2trS.png', '__Affiliation:__ Yozakura Family, Asano Family __Occupation:__ Student, Spy Taiyou is the main protagonist of the series. He is a Spy and member of the Yozakura Family. Taiyou married into the Yozakura Family for the sake of wanting to protect Mutsumi Yozakura and also find out the truth of what happened the day of the car accident which took his parents'' and younger brother''s lives. Taiyou was a cheerful person before he went through the experience of his entire family''s death in a car accid...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-146015', 'Murr', 'anime', 'anilist', '146015', 0.010046064882877586, 'https://s4.anilist.co/file/anilistcdn/character/large/b146015-TTM14WCYx74X.jpg', 'Noé''s cat. Murr never shows any other emotion apart from irritability but seems to care a great deal for Noé - often times lurking in the shadows and watching Noé.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-65007', 'Centorea Shianus', 'anime', 'anilist', '65007', 0.010046064882877586, 'https://s4.anilist.co/file/anilistcdn/character/large/b65007-SFsdhgGf5myf.png', '__Species:__ Centaur Centorea, also known as "Cerea", is the third resident of Kimihito Kurusu''s home. She is very prim and proper, referring to herself as a self-proclaimed knight. As one of the noble creatures, Cerea is incredibly honorable and chivalrous, while being unerringly loyal to Kimihito. Also, she is somewhat archaic in speech and behavior. Centaurs have strict rules about only letting one''s master ride on their backs. She has been shown to be just as possessive of Kimihito as Mii...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-20181', 'Hideyoshi Kinoshita', 'anime', 'anilist', '20181', 0.010046064882877586, 'https://s4.anilist.co/file/anilistcdn/character/large/b20181-fevqFB7qOiK9.jpg', 'Hideyoshi Kinoshita is a class 2-F student in Fumizuki Academy. A classmate of Akihisa since 1st grade. Hideyoshi is the fraternal twin of Yuuko Kinoshita, class ambassador for Class 2-A. He is also a member of the Drama Club. He is one of the most famous characters in the series and in the manga, particularly due to his gender neutrality. Unlike the rest of Class F, Hideyoshi is relatively calm and normal. Hideyoshi remains stoic at most times, but there are times when Hideyoshi loses his ca...');
