INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-248143', 'Hajime Kashimo', 'anime', 'anilist', '248143', 0.00911496618641576, 'https://s4.anilist.co/file/anilistcdn/character/large/b248143-w5ZilMdkvpbe.jpg', 'Hajime Kashimo is a sorcerer from 400 years ago, currently inhabiting the body of someone Kenjaku prepared as a vessel, and has served as a player in the Culling Game, seeking to find and consequently battle Sukuna');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-189848', 'Hee-Won Jung', 'anime', 'anilist', '189848', 0.00911496618641576, 'https://s4.anilist.co/file/anilistcdn/character/large/b189848-SD6SN8SRLagc.png', 'Jung Heewon is a member of Kim Dokja''s party. She was part of the marginalized group from Geumho station. She becomes one of the most vital party members, sometimes referred to as the "sword" of the group.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-160044', 'Haumea', 'anime', 'anilist', '160044', 0.00911496618641576, 'https://s4.anilist.co/file/anilistcdn/character/large/b160044-Vef7Nz9J4OX9.png', 'Haumea is a Third Generation pyrokinetic and a member of the White-Clad. She possesses the Adolla Burst and is known as the Second Pillar.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-154759', 'Mihai Florescu', 'anime', 'anilist', '154759', 0.00911496618641576, 'https://s4.anilist.co/file/anilistcdn/character/large/b154759-xQlDWr0RXBev.png', '__Height:__ 176 cm __Species:__ Vampire Member of the Inugami Detective Agency. Mihai is a several hundred years old vampire Kemono from Romania. Over his life, he has apparently acquired professional-level expertise and knowledge in numerous fields, to the point that he had run out of things to do. Sometime in the past, he became an acquaintance to Kohachi Inugami. When Mihai had started to become disillusioned with life, Inugami asked him to come to Japan and work for the former''s detective...');
