INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-137630', 'Latina', 'anime', 'anilist', '137630', 0.009090463589140448, 'https://s4.anilist.co/file/anilistcdn/character/large/b137630-xrUCqTCrlwr0.png', 'She is a girl of magical descent and [Dale](https://anilist.co/character/137629) finds her abandoned in a forest. The details of her previous life are unknown. She is honest and kind and very smart. She soon becomes an idol for the adventurers who come to the inn. To hide her horns, she wears ribbons in her hair.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-133462', 'Kanade Hisaishi', 'anime', 'anilist', '133462', 0.009090463589140448, 'https://s4.anilist.co/file/anilistcdn/character/large/b133462-dY4Yc9qrhrm5.jpg', '__Instrument:__ Euphonium Kanade Hisaishi is a new first-year at Kitauji High School. She joins the band as a euphonium player in Kumiko''s second year. Kanade has a courteous personality and great communication skills, and gives off a good impression to everyone who sees her. However, she has a secret side to her always-polite demeanor. Kumiko describes her as a "hypocritical courtesy" or a girl who is "superficially polite but rude in intent".');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-71839', 'Noiz', 'anime', 'anilist', '71839', 0.009090463589140448, 'https://s4.anilist.co/file/anilistcdn/character/large/b71839-N7n7kvNjMNVj.jpg', '__Height:__ 179 cm A mysterious man that appears in Aoba''s room unannounced. His body is covered in piercings. He seems to be quite good with technology and leads his own Rhyme team, Ruff Rabbit. (Source: In-game Info)');
