INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-141151', 'Desir Herrman', 'anime', 'anilist', '141151', 0.009065960991865138, 'https://s4.anilist.co/file/anilistcdn/character/large/b141151-u6mLf1y5k7PJ.jpg', '__Magic Circle Rank:__ Tier 3 (Analysis Magic) Desir Herrman is the central protagonist of A Returner’s Magic Should Be Special. After his return to the past upon the failure of clearing the Shadow World, he resolves to strengthen his allies so that the future doesn’t get repeated. In Hebrion Academy, commoners are frowned upon and put into the Beta class whilst the nobles are designated the alpha class, Desir is one of the commoners who hates the class system and wants things to change. As a...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-124685', 'Li Nie', 'anime', 'anilist', '124685', 0.009065960991865138, 'https://s4.anilist.co/file/anilistcdn/character/large/b124685-BgKG6Z1BeA9l.jpg', '__Race:__ Human __Soul Realm:__ Red After dying at the hands of the Sage Emperor, Nie Li wakes up back in his thirteen year old body. Given a second chance to save his loved ones, he is determined to stop Sacred Family from betraying Glory City, and causing the attack that not only destroyed his home but killed all his friends and family. Nie Li is a member of the Heavenly Marks Family, a declining and weak aristocratic family. His initial talent is considered by others to be poor and is lack...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-3763', 'Cibo', 'anime', 'anilist', '3763', 0.009065960991865138, 'https://s4.anilist.co/file/anilistcdn/character/large/b3763-HGLzLifxgoRH.png', 'Cibo is a main character in the manga BLAME! by Tsutomu Nihei. She is the head scientist of the Electronic Corporation in the Capitol and joins Killy on his quest for the Net Terminal Gene. Killy ''s first encounter with Cibo is in the lower levels of the Corporation in The Capitol, where she has been imprisoned for attempting to access the Net Sphere with an artificially created version of Net Terminal Genes. Her failed attempt to access the Net Sphere led to the appearance of the Safeguard, ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-204458', 'Shiori Yomiuri', 'anime', 'anilist', '204458', 0.009041458394589827, 'https://s4.anilist.co/file/anilistcdn/character/large/b204458-BuMrbh0tU6i8.png', 'University student. She works part-time as a senior at the bookstore where Yuuta works. As a caring senior, she supports Yuuta''s "relationship with his younger sister".');
