INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-169484', 'Miko Sakura', 'anime', 'anilist', '169484', 0.008992453200039205, 'https://s4.anilist.co/file/anilistcdn/character/large/b169484-lb6ObyGaywVd.png', '__Debut date:__ August 1, 2018 __Height:__ 152 cm __Fanbase name:__ 35P __Illustrator:__ [ordan](https://anilist.co/staff/175874/) (Original by [Yuuichi Tanaka](https://anilist.co/staff/103540)) __Generation:__ Solo ("0th gen") Sakura Miko is a female Japanese Virtual YouTuber associated with hololive. [Profile (hololive)](https://hololive.hololivepro.com/en/talents/sakuramiko/) | [YouTube](https://www.youtube.com/channel/UC-hM6YJuNYVAmUWxeIr9FeA) | [Twitter](https://twitter.com/sakuramiko35)...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126454', 'Don', 'anime', 'anilist', '126454', 0.008992453200039205, 'https://s4.anilist.co/file/anilistcdn/character/large/b126454-TI3LXk2oN7WV.jpg', '__Age (2045):__ 10 yo __Farm Identifier:__ 16194 __D.O.B:__ 2035/7/4 __Height (2045-2049):__ 155 - 174 cm Don has dark skin and a tall and slender appearance. He has short, messy black hair with an undercut and brown eyes. He wears the standard white uniform. Like [Emma](https://anilist.co/character/121725/Emma), Don cares deeply about his siblings. Don is portrayed as a cheerful and slightly careless boy, however, he too is fairly intelligent, coming around 5th place in the everyday test, af...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126319', 'Nana Shimura', 'anime', 'anilist', '126319', 0.008992453200039205, 'https://s4.anilist.co/file/anilistcdn/character/large/126319-38iRM8zTWazq.png', 'Shimura Nana was the seventh user of the One For All Quirk, All Might''s mentor, and a close friend of Gran Torino.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-27880', 'Kurosawa', 'anime', 'anilist', '27880', 0.008992453200039205, 'https://s4.anilist.co/file/anilistcdn/character/large/b27880-Y5rD5rszTpd5.png', 'A run-of-the-mill guy stuck at his dead-end job. At the very least, he wants people to look up to him. Has pride in his physical strength from his long years doing manual labor.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-7895', 'Noa Izumi', 'anime', 'anilist', '7895', 0.008992453200039205, 'https://s4.anilist.co/file/anilistcdn/character/large/b7895-oT4XfNP2HdzQ.png', 'Section 2, Division 2, Team 1: The bubbly, perky, red-headed labor otaku from Hokkaidō. The main character of the show, Noa is usually the one at the center of the action. Noa loves her labor much like a pet and named it "Alphonse", a name previously held by a pet dog and a pet cat she had while growing up. She''s impulsive and doesn''t think things through, but not nearly as much as Ohta. Noa is arguably the best pilot in Division 2, although both Clancy and Kumagami have shown extreme talent ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-5570', 'Sakuya Izayoi', 'anime', 'anilist', '5570', 0.008992453200039205, 'https://s4.anilist.co/file/anilistcdn/character/large/b5570-UmrjrnC8O5LX.png', 'Sakuya is the only human living in the Scarlet Devil Mansion, yet she is also the head maid. The official fanbook suggests she had been a vampire hunter before she began working in the mansion, but she was defeated by Remilia Scarlet who pitied her and gave Sakuya her current name. Though she looks about sixteen like the other girls, Sakuya has the ability to slow, stop and possibly reverse time. She seems to have been serving Remilia for a long time and may be far older then she looks. Socia...');
