INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-30286', 'Cinnamoroll', 'anime', 'anilist', '30286', 0.008967950602763893, 'https://s4.anilist.co/file/anilistcdn/character/large/b30286-W1HQzqLIGr6N.png', 'Cinnamoroll is Cafe Cinnamon''s official mascot. He is quite shy, but very friendly, and sometimes takes a nap on customers'' laps. He can fly through the air by flapping his huge ears.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-17244', 'Yuusuke Fujisaki', 'anime', 'anilist', '17244', 0.008967950602763893, 'https://s4.anilist.co/file/anilistcdn/character/large/b17244-cmVAMPQmTga9.png', '__School:__ Kaimei High School __Class:__ 2-C (chapters 1-209); 3-C (chapters 210-288) __Affiliation:__ Sket Dan __Special Attack:__ Fujisaki Valencia The founder and leader of the Sket Dan, nicknamed Bossun (ボッスン). Bossun is known for his enthusiasm for helping others solve their problems and is quite idealistic. Given a proper backstory and relationship to his client, he''s willing to go to such lengths to find even lost candy wrappers if the situation calls it. Despite his idealism, he acts...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-2553', 'Isshin Kurosaki', 'anime', 'anilist', '2553', 0.008967950602763893, 'https://s4.anilist.co/file/anilistcdn/character/large/b2553-tDUlab4F0lFJ.png', '__Height:__ 186 cm (6''1") In the beginning of the series, Isshin is portrayed as a silly, fight-loving father who takes a keen interest in what his children are doing, but does it either offensively or with an all-too-happy tone, which elicits comical reactions from his kids, usually in the form of a kick. Isshin also seems to enjoy making fun of Ichigo and has a tendency to talk to the large memorial poster of his late wife Masaki, which he has pinned up in their kitchen, whenever he feels p...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-330063', 'Alicia Williams', 'anime', 'anilist', '330063', 0.008943448005488581, 'https://s4.anilist.co/file/anilistcdn/character/large/b330063-VTL0vaps3PnZ.png', 'Having been reborn as the villainess, she strives to be the best she can be at it; especially as the king has hired her to bully Liz in order to push her out of her comfort zone. She gets more invested in the job as Liz has fans who pick fights and bully anyone who isn''t following blindly. Alicia is very compassionate to the less fortunate, having taken in a child from a village who was banished as her retainer.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-212388', 'Beidou', 'anime', 'anilist', '212388', 0.008943448005488581, 'https://s4.anilist.co/file/anilistcdn/character/large/b212388-L07J15y5CbF2.jpg', '__Origin__: Liyue __Constellation__: Victor Mare As the Captain of the Crux Fleet, Beidou loves travelling the oceans, setting sail with her ship and crew to any place they desire.');
