INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-190866', 'Amber', 'anime', 'anilist', '190866', 0.00891894540821327, 'https://s4.anilist.co/file/anilistcdn/character/large/b190866-PofZZ3L84A3B.png', '__Origin:__ Mondstadt __Constellation:__ Lepus A perky, straightforward girl, who is also the only Outrider of the Knights of Favonius. Her amazing mastery of the glider has made her a three-time winner of the Gliding Champion in Mondstadt. As a rising star within the Knights of Favonius, Amber is always ready for any challenging tasks.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-132795', 'Karin Asaka', 'anime', 'anilist', '132795', 0.00891894540821327, 'https://s4.anilist.co/file/anilistcdn/character/large/b132795-EMhlEfeTQGVT.png', '__Height:__ 167 cm (5''5") Karin Asaka is one of thirteen members of the Nijigasaki High School Idol Club. She is a member of DiverDiva, a unit under Nijigaku. She is a third year student and her image color is royal blue. Karin is very mature and gives off a rather seductive vibe. She believes she is not a cute idol like the others and so confidently uses her more mature charm to capture an audience. Sometimes, she can be very petty and childish. She also has a hard time with directions and g...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127913', 'Kikunojou', 'anime', 'anilist', '127913', 0.00891894540821327, 'https://s4.anilist.co/file/anilistcdn/character/large/b127913-fKFTGlwZA9JH.png', 'Kikunojou is a young woman with long dark hair that falls into her back. She wears sandals and a kimono with chrysanthemum floral patterns. She is a very tall woman, easily towering over Luffy, Zoro, and Tsuru.');
