INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-780', 'Road Kamelot', 'anime', 'anilist', '780', 0.00891894540821327, 'https://s4.anilist.co/file/anilistcdn/character/large/b780-QGegNJEufooQ.jpg', '__Height:__ 148cm (4''10") Road Kamelot is the first Noah introduced in the D. Gray-man series, appearing to Allen, Lenalee, and Miranda in the Rewinding City arc. Despite looking as if she is in her early teens, Road is referred to as the oldest of the Noah. Road has an affinity for candies and blood, as well as a childlike enjoyment of birthday-reminiscent themes. Road has a plethora of supernatural abilities, ranging from the ability to travel to an alternate dimension through a door that a...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-206020', 'Amelia Watson', 'anime', 'anilist', '206020', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/b206020-Ak2mnPwPevN0.jpg', '__Debut date:__ September 13, 2020 __Retirement date:__ September 30, 2024 (from streaming activities) __Height:__ 150 cm __Fan base name:__ Teamates __Illustrator:__ [NABI](https://anilist.co/staff/190352) __Generation:__ EN 1st Gen (holoMyth) Watson Amelia is a female English Virtual YouTuber associated with hololive''s English branch. Despite ending her streaming activities in September 2024, Amelia remains affiliated with hololive and is expected to return in future projects. [Profile (hol...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-129138', 'Nicol Ascart', 'anime', 'anilist', '129138', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/b129138-RPrD5nPakxZl.jpg', '__Magic Type: Wind__ The fourth capturable character of the otome game Fortune Lover. He’s the taciturn, expressionless son of the prime minister, and also a capture target. With black hair and eyes, and a perfect doll-like face, he’s a handsome boy with a devilish charm that can even capture men as well as women with his unique atmosphere. Game Description: Nicole Ascarot, the prime minister’s son, Alan and Gerald’s childhood friend. He’s one year older than the heroine, and is a taciturn se...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127594', 'Natsuo Fujii', 'anime', 'anilist', '127594', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/b127594-HhC0gZYT2fkE.jpg', '__Height:__ 178 cm (5''10") Natsuo Fujii is the main male protagonist of [Domestic na Kanojo](https://anilist.co/anime/103139/Domestic-na-Kanojo/). He is introduced as a second-year high school student who loves writing novels, so he frequently heads to the rooftop during his lunch breaks to develop his passion. It is there that he meets the rookie English teacher named [Hina Tachibana](https://anilist.co/character/127595/Hina-Tachibana), who becomes his first crush. His current appearance is ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-125877', 'Mitty', 'anime', 'anilist', '125877', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/b125877-nFoMWC2T67Tx.jpg', '**Species**: Narehate Mitty is an amorphous Narehate who lived with Nanachi on the 4th layer of the Abyss. Mitty had been a regular human girl in the past and her appearance changed due to the result of the ascension from the 6th layer.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-89162', 'Zest', 'anime', 'anilist', '89162', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/89162-ljGq9O0Jhk0n.jpg', 'Zest is a Demon who originally served her creator, the Demon marquis Zolgear, as his aide.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-22646', 'Ivankov Emporio', 'anime', 'anilist', '22646', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/22646.jpg', '__Devil Fruit:__ Horu Horu no Mi (Horm-Horm Fruit) __Devil Fruit Type:__ Paramecia Emporio Ivankov, Iva for short, is the former &quot;Queen&quot; of the Kamabakka Kingdom, who is known as a &quot;Miracle Person&quot;, and a commander of the Revolutionaries army. He is currently a prisoner of Impel Down kept in Level 5, but lives in a secret &quot;Okama Paradise&quot; within the same level.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-740', 'Nana', 'anime', 'anilist', '740', 0.00889444281093796, 'https://s4.anilist.co/file/anilistcdn/character/large/b740-ODhefJgbwzMK.png', 'Also known as Number 7, she is a young Silpelit girl who has the physical appearance of being 12-14 years old (though because Silpelits age rapidly, she is actually only about 6 years old). Her name, ''Nana'', is Japanese for the number seven, the number by which she was called at the research facility ("Nana" is also a fairly common female name in Japan). Most diclonius babies are euthanized at birth in sweeps of hospital maternity wards, but Nana was one of a handful kept alive for use as a t...');
