INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-184429', 'Kai Yang', 'anime', 'anilist', '184429', 0.006983240223463687, 'https://s4.anilist.co/file/anilistcdn/character/large/b184429-I38Np4MIZThG.png', '__Species:__ Human (Former) Yang Kai was a trial disciple in High Heaven Pavilion and the ninth Young Master of the Yang Family which was of the Eight Great Families of Nine Continents. One day, he stumbled upon a Black Book,');
