INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126257', 'Jiren', 'anime', 'anilist', '126257', 0.00683622463981182, 'https://s4.anilist.co/file/anilistcdn/character/large/b126257-nGjgbsnxZkUB.png', 'Jiren is a man who devotes everything to justice and never acts for selfish reasons; he lives to protect Universe 11, even stating that he would leave the tournament while it was happening in order to return there if any problem arose in the 48 minutes of the tournament.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-90017', 'Hiyoko Saionji', 'anime', 'anilist', '90017', 0.00683622463981182, 'https://s4.anilist.co/file/anilistcdn/character/large/b90017-RWI8SgVL9IXt.jpg', '__Height:__ 130 cm __Talent:__ Ultimate Traditional Dancer She appears as an innocent girl, but she can be extremely rude. She calls Togami "Mr. Porkfeet" and Tsumiki "Dirty Bitch."');
