INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-145098', 'Francois', 'anime', 'anilist', '145098', 0.006787219445261197, 'https://s4.anilist.co/file/anilistcdn/character/large/b145098-T5TSpMoyy3cR.jpg', '__Height:__ 160cm (5''3") Francois is [Ryuusui](https://anilist.co/character/145097/Ryuusui-Nanami)''s faithful and extremely talented butler whose services were well sought out and coveted before the Petrification. Their gender remains unknown. They are demonstrated to be a supreme chef. (Source: Dr. Stone Wiki)');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-89855', 'Ichiyou Higuchi', 'anime', 'anilist', '89855', 0.006787219445261197, 'https://s4.anilist.co/file/anilistcdn/character/large/89855-wWUfJVCKhGOJ.png', 'A beautiful and intelligent woman who wears pants. She belongs to a commando unit that answers to the leader of Port Mafia, and has authority over the military group "Black Lizard." She adores Akutagawa and calls him "senpai."');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-13583', 'Itto Ogami', 'anime', 'anilist', '13583', 0.006787219445261197, 'https://s4.anilist.co/file/anilistcdn/character/large/13583-hIFgRILh5vGd.png', 'Ogami Itto seemed to have a very cushy life during Edo-Era Japan, for he had been the Shogun''s official executioner (Kogi Kaishakunin). A position so powerful, the term "Second" meant that Itto was only second to the Shogun as far as metering out death to unloyal feudal lords throughout the 60 regions of Shogunate controlled Japan. In fact, the Shogun''s symbol of the Hollyhock crest was a noticable part of Ogami''s court attire, thus deeming his stature as indeed being the Shogun''s final say o...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-12069', 'Neku Sakuraba', 'anime', 'anilist', '12069', 0.006787219445261197, 'https://s4.anilist.co/file/anilistcdn/character/large/b12069-BXcq95f1oUc7.png', 'An antisocial, graffiti-loving kid who keeps his headphones on to shut the world out. He awakens in the middle of Shibuya''s Scramble Crossing and immediately realizes that something is amiss...');
