INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-226254', 'Rody Soul', 'anime', 'anilist', '226254', 0.006738214250710576, 'https://s4.anilist.co/file/anilistcdn/character/large/b226254-TgPDmuHpjn34.png', '__Quirk:__ Soul Original character from My Hero Academia The Movie: World Heroes'' Mission. Rody is a very carefree individual who always looks for an opportunity/job to support his younger brother and sister and make their lives better. He is a smooth liar and a good negotiator, able to talk his way out of most situations.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-154747', 'Kohachi Inugami', 'anime', 'anilist', '154747', 0.006738214250710576, 'https://s4.anilist.co/file/anilistcdn/character/large/b154747-onCg5tNXWVkS.png', '__Height__: 180 cm __Species__: Bakedanuki A detective that specializes in the occult. Inugami runs a Kemono detective agency in Tokyo. After meeting Kabane, he took him with him in order to help him find his parents. Inugami is a calm person who doesn''t like conflict and is kind enough to follow Kabane and the others casually. He is good at taking care of the children, even helping them in their own various circumstances. As the head of the detective agency, he is good at solving and making ...');
