INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-1859', 'Lambo', 'anime', 'anilist', '1859', 0.006738214250710576, 'https://s4.anilist.co/file/anilistcdn/character/large/b1859-FMaxQi2KIvKH.png', '__Nationality:__ Japanese/Italian __Favorite Food:__ Grapes and Candies __Mafia:__ Vongola/Bovino __Occupation:__ Assassin __Vongola Ring:__ Ring of Thunder __Box Weapon:__ Gyuudon (Vongola Lightning Bull aka Beef Bowl) Lambo is a hitman assassin from Italy''s Bovino family. He is also the self proclaimed rival of Reborn. His main choice of weapons are hand grenades and horns, and his future dream is to rule the world. Lambo dresses in a cow suit complete with a tail, and has a huge afro with ...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-305653', 'Yuusei Shirosaki', 'anime', 'anilist', '305653', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b305653-fmenHf6rPHZd.png', '__Height:__ 181 cm He is the chief of the Planning and Sales department at Minette whose concentration at work is high and his performance is good. In matters outside of work, he gets easily distracted and often makes mistakes.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-281251', 'Yuusuke Tani', 'anime', 'anilist', '281251', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b281251-fpCKCGSQH6Rv.png', '__Height:__ 171 cm (5''7") A quiet boy who clearly states his opinions. [Suzuki](https://anilist.co/character/281250/Miyu-Suzuki) always approaches him with a lighthearted vibe, but he always seems to reply curtly.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-137506', 'Kurogiri', 'anime', 'anilist', '137506', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b137506-EzqPO6yHvjcK.jpg', '__Affiliation:__ League of Villains __Quirk:__ Warp Gate Kurogiri has a level-headed personality, which often serves to ground Tomura Shigaraki''s immaturity. He is intensely loyal to both All For One and Tomura. He is very polite and well-spoken, even to enemies.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-135191', 'Anonymous', 'anime', 'anilist', '135191', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b135191-Cqy57M8FGQGD.jpg', 'Anonymous is the mysterious founder and owner of the Lounge. They are asexual and, as Kamatani Yuuki has stated, of indeterminate gender identity.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127204', 'Kirishima Miyama', 'anime', 'anilist', '127204', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b127204-iGdXW72BeWYF.png', 'Yoshino''s fiance. His grandfather is the president of the Miyama group, a yakuza organization in the Kantou region.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-127015', 'Chisaki Miyazaki', 'anime', 'anilist', '127015', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/127015-on0C7x9I5jMu.jpg', 'A girl who befriends Kogarashi after meeting him during the first day of high school. She is also a popular girl at school, known for her beauty.');
