INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-90194', 'Sayaka Miyata', 'anime', 'anilist', '90194', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b90194-gAoabRI1uF5U.jpg', 'Kaminashi''s first friend and rival. Before Keijo used to be a judo''s athlete, she was the Japan''s hope for a golden medal in the Olympics but threw it all away in the qualifications. She has a complex about her bust size and Kaminashi usually makes fun about it. She previously resided in Room 309 before being promoted to the Elite Class. Upon graduating from Setouchi, Sayaka officially becomes a B-Rank Keijo player, affiliated with the Kansai''s Hyougo Branch.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-90101', 'Freyja Wion', 'anime', 'anilist', '90101', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b90101-Cj2zBEbVPgOg.jpg', NULL);
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-89647', 'Nene Sakura', 'anime', 'anilist', '89647', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b89647-ulMABzKQOOmi.jpg', '**Birthplace:** Tokyo **Height:** 144 cm Aoba''s friend from high school who is currently in university. She took an interest in programming and eventually became an intern at Eagle Jump after beta testing Fairies Story 3. Nene is described as childish, selfish, and goofy by Aoba, who can''t stay focused on the task given to her, which is why she''s often seen leaving her post. She is also an otaku and a fan of Faries Story Series.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-88605', 'Hatoko Kushikawa', 'anime', 'anilist', '88605', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/b88605-Tut2zmYtRJsd.png', 'Hatoko Kushikawa is one of the main characters of Ino Battle wa Nichijo-kei no Naka de. She is also a part of the Literature Club. She is a polite air-headed girl who often takes Jurai''s chunibyo antics seriously. Her power is "Over Element," which gives her the ability to manipulate five main elements of the natural world: earth, water, fire, wind, and light. She is also Jurai''s childhood friend and next door neighbor, who sometimes drops by to his house to cook for him and his big sister, s...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-21563', 'Chun-Woo Han', 'anime', 'anilist', '21563', 0.006713711653435264, 'https://s4.anilist.co/file/anilistcdn/character/large/21563.jpg', 'Teacher who has mastered 9 styles of martial arts. With a mysterious past who seems to hold a grudge for the martial artists federation relating to the death of his master. At the beginning of the story he seems to be a perverted middle aged man who came to the school going undercover as a teacher. After Shioon discovering his martial art skills, shioon bribes him with a video clip. Continuing Chun woo discovers Shioon''s hidden potential and teaches foot and arm techiniques.As the story progr...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-290559', 'Si-Yun Baek', 'anime', 'anilist', '290559', 0.006689209056159953, 'https://s4.anilist.co/file/anilistcdn/character/large/b290559-R6mbDMgmoBwW.jpg', 'A mysterious man who enters Jeongmin''s lucid dreams.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-203167', 'Mylene Rafa Holfort', 'anime', 'anilist', '203167', 0.006689209056159953, 'https://s4.anilist.co/file/anilistcdn/character/large/b203167-rdyGeGPTcFIq.png', 'Mylene Rafa Holfort is the mother of Julius, wife of Roland and the Queen of Holfort Kingdom.');
