INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126248', 'Nagi Rokuya', 'anime', 'anilist', '126248', 0.00622365970792904, 'https://s4.anilist.co/file/anilistcdn/character/large/b126248-TQtG2jVaVvdb.png', '__Height:__ 180 cm Nagi Rokuya remarkably good looks and high charisma combine to turn him into a bit of a flirting machine, he''s often see flirting with women. His charisma is a double-edged sword, however, as his personality and looks combined made it so he didn’t have many friends growing up. As a result, he loves IDOLiSH7 more than anyone else. In times of strife, it’s usually Nagi’s very obvious love for his friends that manages to bring smiles back to their faces.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-120858', 'Takuru Miyashiro', 'anime', 'anilist', '120858', 0.00622365970792904, 'https://s4.anilist.co/file/anilistcdn/character/large/b120858-8eTgjuxB5Ufx.jpg', 'A diligent third-year high school student and President of the Newspaper Club. His parents died during the earthquake six years ago. Since then, he has taken shelter in the mobile home near Miyashita Public Park.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-6038', 'Akihiko Usami', 'anime', 'anilist', '6038', 0.00622365970792904, 'https://s4.anilist.co/file/anilistcdn/character/large/6038.jpg', '__Date of Birth:__ March 3 __Zodiac:__ Pisces A 28-year-old author. He was raised in England until he was 10, and later moved to Japan. He graduated law school first of his class and is the youngest recipient of the Naomori Award. He was a pure-hearted romanticist, as Takahashi Misaki, his love interest says. He is extremely popular with his books, but also writes erotic (BL) Yaoi fiction under the pen name Akikawa Yayoi because it allows him to earn money on his fantasies. He is working for ...');
