INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-133817', 'Tatsuya Fukuda', 'anime', 'anilist', '133817', 0.006027638929726551, 'https://s4.anilist.co/file/anilistcdn/character/large/b133817-DWltAyBhJzxf.png', '__Height:__ 176 cm Director of Tokyo City Esperion FC Youth, and Head Coach of the A Team. He was born in Ehime, Japan but moved to Tokyo to attend high school. He joined Tokyo City Esperion FC of the J-League (Japan''s top professional football league) at the age of 18 and became a regular at 20. At 23 he was signed by the Spanish club Sabadell FC who had been recently promoted to Spain''s top division, La Liga. A while later, his mother married [Hana Ichijou](https://anilist.co/character/1620...');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126663', 'Kaoruko Hanayagi', 'anime', 'anilist', '126663', 0.006027638929726551, 'https://s4.anilist.co/file/anilistcdn/character/large/b126663-x1xNZWPZPpXl.png', 'Kaoruko Hanayagi is a character in the Shōjo☆Kageki Revue Starlight franchise. She is a second-year student from the Actor Training Department at Seisho Music Academy''s 99th Graduating Class. Granddaughter of the head of a traditional Japanese dance school, this Stage Girl has refined skills in traditional song and dance. Raised in privilege, she is all too reliant on Futaba Isurugi. While she is always smiling, she is more calculating than anyone else. Speaks in the elegant Kyoto dialect.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-126609', 'Ayano Hanesaki', 'anime', 'anilist', '126609', 0.006027638929726551, 'https://s4.anilist.co/file/anilistcdn/character/large/b126609-NIlALZDHoMIc.png', 'Hanesaki Ayano is the protagonist of Hanebado! and a 1st year member of the Kitakomachi badminton club.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-121231', 'Biao Gong', 'anime', 'anilist', '121231', 0.006027638929726551, 'https://s4.anilist.co/file/anilistcdn/character/large/121231-uTEKI2nmCXxN.jpg', 'Biao Gong is a Great General from the state of Qin who led an invading Qin army to besiege the Wei city of Keiyou. He is known for being an instinctive general for his use of crude tactics and striking after upsetting the battlefield with his use of infantry. The Duke''s skills at war have made him a great asset to the state of Qin.');
INSERT OR IGNORE INTO characters (id, name, category, source, source_id, popularity, image_url, description) VALUES ('anilist-70407', 'Ukyo', 'anime', 'anilist', '70407', 0.006027638929726551, 'https://s4.anilist.co/file/anilistcdn/character/large/b70407-pptT3LlZqnke.png', '__Occupation:__ Photographer Ukyo is a tall, slim young man with waist-length green hair and green eyes. His bangs fall freely over his face, down to his cheeks, and there is a long braid on Ukyo''s right, held together using a white hair-band. His symbolic route in the game is the "Joker." (Source: Wikipedia, Amnesia wiki)');
