-- ============================================================
-- migrations/0017_attribute_count.sql
-- ============================================================
-- Denormalized attribute_count column on characters to replace the correlated
-- subquery in game/start.ts (SELECT ... GROUP BY character_id HAVING COUNT(*) >= N)
-- with a simple indexed equality check (attribute_count >= N).

ALTER TABLE characters ADD COLUMN attribute_count INTEGER NOT NULL DEFAULT 0;

-- Backfill from existing data
UPDATE characters SET attribute_count = (
  SELECT COUNT(*)
  FROM character_attributes
  WHERE character_id = characters.id AND value IS NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_characters_attr_count ON characters(attribute_count);

-- ── Triggers to keep attribute_count in sync automatically ───────────────────

-- New non-null attribute inserted
CREATE TRIGGER IF NOT EXISTS trg_attr_count_insert
AFTER INSERT ON character_attributes
FOR EACH ROW
WHEN NEW.value IS NOT NULL
BEGIN
  UPDATE characters SET attribute_count = attribute_count + 1
  WHERE id = NEW.character_id;
END;

-- Non-null attribute deleted
CREATE TRIGGER IF NOT EXISTS trg_attr_count_delete
AFTER DELETE ON character_attributes
FOR EACH ROW
WHEN OLD.value IS NOT NULL
BEGIN
  UPDATE characters SET attribute_count = MAX(0, attribute_count - 1)
  WHERE id = OLD.character_id;
END;

-- Attribute value changed (NULL ↔ non-NULL, or true ↔ false)
-- Full recount is safer than trying to track the delta
CREATE TRIGGER IF NOT EXISTS trg_attr_count_update
AFTER UPDATE OF value ON character_attributes
FOR EACH ROW
BEGIN
  UPDATE characters SET attribute_count = (
    SELECT COUNT(*)
    FROM character_attributes
    WHERE character_id = NEW.character_id AND value IS NOT NULL
  ) WHERE id = NEW.character_id;
END;


-- ============================================================
-- migrations/0018_fts_search.sql
-- ============================================================
-- FTS5 virtual table for fast full-text character name search.
-- Replaces the leading-wildcard LIKE '%search%' query (which causes a full table scan)
-- with an inverted index MATCH lookup, then joins back to characters for filtering.

CREATE VIRTUAL TABLE IF NOT EXISTS characters_fts USING fts5(
  name,
  content='characters',
  content_rowid='rowid',
  tokenize='unicode61 remove_diacritics 1'
);

-- Populate with existing data
INSERT INTO characters_fts(rowid, name)
SELECT rowid, name FROM characters;

-- ── Sync triggers ─────────────────────────────────────────────────────────────

CREATE TRIGGER IF NOT EXISTS characters_fts_ai
AFTER INSERT ON characters BEGIN
  INSERT INTO characters_fts(rowid, name) VALUES (new.rowid, new.name);
END;

CREATE TRIGGER IF NOT EXISTS characters_fts_ad
AFTER DELETE ON characters BEGIN
  INSERT INTO characters_fts(characters_fts, rowid, name) VALUES ('delete', old.rowid, old.name);
END;

CREATE TRIGGER IF NOT EXISTS characters_fts_au
AFTER UPDATE ON characters BEGIN
  INSERT INTO characters_fts(characters_fts, rowid, name) VALUES ('delete', old.rowid, old.name);
  INSERT INTO characters_fts(rowid, name) VALUES (new.rowid, new.name);
END;


-- ============================================================
-- migrations/0019_attributes_json.sql
-- ============================================================
-- Denormalized attributes_json column on characters.
-- Stores all non-null attributes as a JSON object { attribute_key: 0|1 }.
-- Eliminates the large character_attributes JOIN in game/start.ts and game/resume.ts
-- (reduces D1 payload from ~25-50K rows down to 500 rows for a typical pool).

ALTER TABLE characters ADD COLUMN attributes_json TEXT NOT NULL DEFAULT '{}';

-- Backfill from existing character_attributes
UPDATE characters SET attributes_json = COALESCE(
  (SELECT json_group_object(attribute_key, value)
   FROM character_attributes
   WHERE character_id = characters.id AND value IS NOT NULL),
  '{}'
);

-- ── Sync triggers ─────────────────────────────────────────────────────────────

-- New non-null attribute inserted
CREATE TRIGGER IF NOT EXISTS trg_attrs_json_insert
AFTER INSERT ON character_attributes
FOR EACH ROW
WHEN NEW.value IS NOT NULL
BEGIN
  UPDATE characters SET attributes_json = COALESCE(
    (SELECT json_group_object(attribute_key, value)
     FROM character_attributes
     WHERE character_id = NEW.character_id AND value IS NOT NULL),
    '{}'
  ) WHERE id = NEW.character_id;
END;

-- Non-null attribute deleted (set to NULL or removed)
CREATE TRIGGER IF NOT EXISTS trg_attrs_json_delete
AFTER DELETE ON character_attributes
FOR EACH ROW
WHEN OLD.value IS NOT NULL
BEGIN
  UPDATE characters SET attributes_json = COALESCE(
    (SELECT json_group_object(attribute_key, value)
     FROM character_attributes
     WHERE character_id = OLD.character_id AND value IS NOT NULL),
    '{}'
  ) WHERE id = OLD.character_id;
END;

-- Attribute value changed
CREATE TRIGGER IF NOT EXISTS trg_attrs_json_update
AFTER UPDATE OF value ON character_attributes
FOR EACH ROW
BEGIN
  UPDATE characters SET attributes_json = COALESCE(
    (SELECT json_group_object(attribute_key, value)
     FROM character_attributes
     WHERE character_id = NEW.character_id AND value IS NOT NULL),
    '{}'
  ) WHERE id = NEW.character_id;
END;


-- ============================================================
-- migrations/0020_sim_game_stats.sql
-- ============================================================
-- Simulation game stats table.
-- Stores results from headless game simulations (scripts/simulate/run.ts).
-- Kept separate from game_stats so synthetic data never pollutes real-game analytics.

CREATE TABLE IF NOT EXISTS sim_game_stats (
  id                        INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id                    TEXT    NOT NULL,  -- UUID grouping all games in one simulation batch
  target_character_id       TEXT    NOT NULL,
  target_character_name     TEXT    NOT NULL,
  won                       INTEGER NOT NULL,  -- 0|1
  questions_asked           INTEGER NOT NULL,
  guesses_used              INTEGER NOT NULL DEFAULT 0,
  guess_trigger             TEXT,              -- 'singleton'|'max_questions'|'high_certainty'|'strict_readiness'|'insufficient_data'
  forced_guess              INTEGER NOT NULL DEFAULT 0,
  confidence_at_guess       REAL,
  entropy_at_guess          REAL,
  gap_at_guess              REAL,
  alive_count_at_guess      INTEGER,
  second_best_character_id  TEXT,              -- character most confused with target
  second_best_character_name TEXT,
  second_best_probability   REAL,
  questions_sequence        TEXT,              -- JSON: [{attribute, answer, infoGain}]
  answer_distribution       TEXT,             -- JSON: {yes, no, maybe, unknown}
  character_pool_size       INTEGER,
  max_questions             INTEGER,
  difficulty                TEXT    NOT NULL DEFAULT 'medium',
  created_at                INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_sim_target ON sim_game_stats (target_character_id);
CREATE INDEX IF NOT EXISTS idx_sim_run    ON sim_game_stats (run_id);
CREATE INDEX IF NOT EXISTS idx_sim_won    ON sim_game_stats (won, created_at);
CREATE INDEX IF NOT EXISTS idx_sim_created ON sim_game_stats (created_at DESC);


