);

CREATE INDEX IF NOT EXISTS idx_error_logs_created ON error_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_error_logs_level   ON error_logs(level, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_error_logs_source  ON error_logs(source, created_at DESC);


-- ============================================================
-- migrations/0028_dedup_attributes.sql
-- ============================================================
-- Migration 0028: Deduplicate attribute pairs and deactivate zero-info attributes
-- 
-- Problem: Three duplicate attribute pairs split character_attributes coverage, reducing
-- per-attribute info gain. Two zero-info attributes waste question budget.
--
-- Duplicate pairs (winner → loser):
--   fromVideoGame   → isVideoGameCharacter
--   fromMovie       → isFromMovie
--   fromBook        → isFromBook
--
-- Zero-info attributes (deactivate, not delete — preserves history):
--   isFictional     (all game characters are fictional → ~0 info gain)
--   isReal          (inverse of isFictional → same problem)
--   livesInNewYork  (hyperspecific single-city geography with no peer attributes)

-- NOTE: The INSERT OR IGNORE ... SELECT merge step was removed because it causes
-- SQLITE_NOMEM on D1 when character_attributes is large (builds full result set in memory).
-- Trade-off: characters that ONLY had the loser key (not the canonical key) will lose
-- that attribute — re-run the enrichment pipeline to restore coverage for those characters.

-- ── Step 1: Remove loser character_attribute rows ─────────────────────────────────────

DELETE FROM character_attributes
WHERE attribute_key IN ('isVideoGameCharacter', 'isFromMovie', 'isFromBook');

-- ── Step 2: Remove loser questions ────────────────────────────────────────────────────

DELETE FROM questions
WHERE attribute_key IN ('isVideoGameCharacter', 'isFromMovie', 'isFromBook');

-- ── Step 3: Remove loser attribute definitions ────────────────────────────────────────

DELETE FROM attribute_definitions
WHERE key IN ('isVideoGameCharacter', 'isFromMovie', 'isFromBook');

-- ── Step 4: Deactivate zero-info attributes ────────────────────────────────────────────

UPDATE attribute_definitions
SET is_active = 0
WHERE key IN ('isFictional', 'isReal', 'livesInNewYork');


-- ============================================================
-- migrations/0029_fill_missing_questions.sql
-- ============================================================
-- Migration 0029: Fill missing questions table rows for active attributes
--
-- Problem: Some attribute_definitions rows with question_text have no corresponding
-- row in the questions table, so selectBestQuestion never picks them.
--
-- Solution: Insert a questions row for any active attribute that has question_text
-- but no existing questions row. Uses 'q_fill_<key>' as the ID prefix.

INSERT OR IGNORE INTO questions (id, text, attribute_key, priority)
SELECT
  'q_fill_' || ad.key AS id,
  ad.question_text     AS text,
  ad.key               AS attribute_key,
  1.0                  AS priority
FROM attribute_definitions ad
WHERE ad.is_active = 1
  AND ad.question_text IS NOT NULL
  AND ad.question_text != ''
  AND NOT EXISTS (
    SELECT 1 FROM questions q WHERE q.attribute_key = ad.key
  );


-- ============================================================
-- migrations/0030_question_difficulty.sql
-- ============================================================
-- Migration 0030: Add difficulty column to questions table
--
-- Purpose: Allows classifying questions by difficulty level so the game engine
-- can soft-filter mismatched questions (0.5× score penalty) when game difficulty
-- is set. Classification is done offline via scripts/classify-difficulty.ts.
--
-- Difficulty semantics:
--   easy   – binary, universally known (is it human? does it have a weapon?)
--   medium – requires some pop-culture knowledge (is it royalty? has a sidekick?)
--   hard   – niche or very specific (has tentacles? can regenerate? shoots lasers?)

ALTER TABLE questions ADD COLUMN difficulty TEXT
  CHECK (difficulty IN ('easy', 'medium', 'hard'))
  DEFAULT NULL;

